#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


# Cutover to servis.lisztrapszodia.in.rs (#18). Run from the repo root, with
# the Railway CLI logged in and linked to the production environment:
#   scripts/cutover.sh
# Set RAILWAY_SERVICE if the app isn't the linked service. Nothing here touches
# sb.lisztrapszodia.in.rs or its DNS.

TOTAL_STAGES=10

FIREBASE_PROJECT="servicebook-fa47f"
EXPORT_URL="https://${FIREBASE_PROJECT}.firebaseio.com/.json"
RULES_URL="https://console.firebase.google.com/project/${FIREBASE_PROJECT}/database/${FIREBASE_PROJECT}/rules"
NEW_APP="https://servis.lisztrapszodia.in.rs"
OLD_APP="https://sb.lisztrapszodia.in.rs"
ARCHIVE="$HOME/Downloads/servicebook-firebase-export-$(date +%F).json"

# rail CMD… runs CMD in the production app container.
rail() { railway ssh ${RAILWAY_SERVICE:+--service "$RAILWAY_SERVICE"} -- "$@"; }
import_legacy() { rail npm --prefix /workspace/apps/backend run -s import:legacy -- "$EXPORT_URL" "$@"; }
# export_status prints the HTTP status of a public read of the Firebase database.
export_status() { curl -s -o /dev/null -w '%{http_code}' "${EXPORT_URL}?shallow=true"; }
abort() { printf '\n'; warn "$1"; note "Nothing after this point was done. Fix it, then re-run the wizard."; exit 1; }

banner "Cutover: old Firebase app → $NEW_APP"

# ──────────────────────────────────────────────────────────────────────────
stage "Preflight"
say "Checking the Railway CLI, the production container and the Firebase export."
command -v railway >/dev/null 2>&1 || abort "The Railway CLI isn't installed (brew install railway)."
railway status || abort "Run 'railway login' and 'railway link' (project service-book, environment production)."
rail true || abort "Couldn't open a shell in the production container (railway ssh)."
# Every check below trusts railway ssh to pass on the command's exit code.
! rail false || abort "railway ssh doesn't pass on exit codes, so the wizard can't tell failures apart."
if rail grep -q readExport /workspace/apps/backend/src/scripts/importLegacy.ts; then
  printf '  %s✓%s production runs a build whose import reads straight from Firebase\n' "$GREEN" "$RESET"
else
  abort "Production doesn't have the latest import script yet: push master, wait for the deploy, re-run."
fi
[[ "$(export_status)" == 200 ]] || abort "The Firebase export isn't publicly readable at $EXPORT_URL."
printf '  %s✓%s the Firebase export is readable\n' "$GREEN" "$RESET"
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Production starts empty"
say "The import should land in a database with no services of its own."
open_url "$NEW_APP"
step "Log in and open Services. Delete any test services you made there."
note "Service numbers come from per-year counters that never go back, so if"
note "services were ever created in production, imported 2026 services are"
note "numbered after them. To restart the counters (only with zero services):"
note "  railway connect Postgres   then   DELETE FROM service_number_counter;"
confirm "Production has no services of its own?" || abort "Clear production first."

# ──────────────────────────────────────────────────────────────────────────
stage "Freeze the old app"
step "Tell staff: from now on, don't enter anything in $OLD_APP."
say "Then make the old database read-only, so nothing slips in after the export:"
open_url "$RULES_URL"
step "Realtime Database → Rules (if the link misses: Build → Realtime Database → Rules)."
step "Replace the rules with the following, then click Publish:"
printf '\n      { "rules": { ".read": true, ".write": false } }\n\n'
note "Reads stay open: the import fetches the export from that URL."
pause "Press Enter once the rules are published"
[[ "$(export_status)" == 200 ]] || abort "The export stopped being readable; keep \".read\": true until stage 9."

# ──────────────────────────────────────────────────────────────────────────
stage "Dry run against production"
say "Fetches the final export in the container and reports. Writes nothing."
import_legacy --dry-run || abort "The dry run failed."
printf '\n'
note "Expected (export of 20 Oct 2026): ~356 customers, ~1280 devices, 253 actions,"
note "~1116 services, plus whatever staff added since. Expected anomalies: placeholder"
note "manufacturers (NA), 2019 'title' fields, sold/serviced flag mismatches, one"
note "rounded price. Expected skip: the stray 'false' key."
confirm "Is the report free of unexplained anomalies?" || abort "Look into the report before importing."

# ──────────────────────────────────────────────────────────────────────────
stage "Import"
say "Applies the import in one transaction. Re-running it is safe (upserts by legacy ID)."
confirm "Import into production now?" || abort "Import skipped."
import_legacy || abort "The import failed; the transaction rolled back, so nothing was written."
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Spot-check against the old app"
open_url "$NEW_APP"
open_url "$OLD_APP"
step "Counts: the Services, Customers and Devices lists show as many as the old app's."
note "The dry-run report's counts are what the old database holds, if a list hides them."
step "Open a few services side by side: the oldest (2019), one with sold devices, the newest."
step "Compare customer, devices, lines, status, remark (Log tab) and total."
note "Totals are now Σ quantity × unit price over every line, sold devices included."
note "Where the old app got that wrong, the new total is the right one."
confirm "Do the counts and sample services match?" || abort "Investigate before going live."

# ──────────────────────────────────────────────────────────────────────────
stage "Delete the test service"
open_url "$NEW_APP"
step "Services → search \"Test za novi app\" → open it → delete it."
step "Its device was only ever on that service; delete it from Devices if it's a test one too."
warn "Re-running the import brings it back; delete it again if you ever do."
pause "Press Enter once it's deleted"

# ──────────────────────────────────────────────────────────────────────────
stage "Staff go live"
say "Each staff member needs an account (there is no sign-up). In the shell that opens, run"
say "once per person, then type exit:"
printf '\n      cd /workspace/apps/backend\n      npm run staff:create -- <email> <password> "<Name>"\n\n'
if confirm "Open a production shell to create accounts?"; then
  railway ssh ${RAILWAY_SERVICE:+--service "$RAILWAY_SERVICE"} || warn "The shell exited with an error."
fi
step "Send each staff member $NEW_APP with their email and password."
step "Have one of them log in and open a service, to be sure."
confirm "Are staff working on $NEW_APP?" || abort "Get staff onto the new app first; the old database stays readable."

# ──────────────────────────────────────────────────────────────────────────
stage "Lock the Firebase database"
say "Keeping a final copy of the export first, since the URL stops working after this:"
mkdir -p "$(dirname "$ARCHIVE")"
curl -sf "$EXPORT_URL" -o "$ARCHIVE" || abort "Couldn't download the export."
printf '  %s✓ saved%s %s\n' "$GREEN" "$RESET" "$ARCHIVE"
note "It holds customer data: keep it private, never commit it."
open_url "$RULES_URL"
step "Replace the rules with the following, then click Publish:"
printf '\n      { "rules": { ".read": false, ".write": false } }\n\n'
pause "Press Enter once the rules are published"
step "In the old app, try saving any change: it should fail (or vanish on reload)."
status=$(export_status) || status=000
if [[ "$status" == 401 ]]; then
  printf '  %s✓%s public reads are denied (HTTP 401)\n' "$GREEN" "$RESET"
else
  SKIPPED+=("Firebase rules: a public read still returns HTTP $status, expected 401")
  warn "A public read still returns HTTP $status; check the rules were published."
fi
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Watch Sentry"
open_url "https://sentry.io/issues/"
step "Check the backend and admin-panel projects daily for the first few days."
note "$OLD_APP still serves the old app, which can no longer read or write."
note "Deactivate it when you're ready; nothing in this project touches it."
pause "Press Enter to finish"

finish
